<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DataTable from './DataTable.vue'
defineProps<{run: Record<string, any>}>()
const route=useRoute(),router=useRouter()
const tabs=['hosts','ports','services','endpoints','credentials','screenshots','cve','events']
const metrics=['hosts','open_ports','services','endpoints','credentials','screenshots','errors']
const tab=computed(()=>tabs.includes(String(route.query.tab))?String(route.query.tab):'hosts')
const fields:Record<string,string[]>={hosts:['hostname','ip','source','status','open_ports','services','first_seen_at','last_seen_at'],ports:['hostname','ip','port','transport','state','change'],services:['hostname','ip','port','transport','name','product','version','banner','confidence','details','change','first_seen_at','last_seen_at'],endpoints:['hostname','url','ip','port','source','status','details','screenshot'],credentials:['url','username','credential_id','status','evidence','attempted_at'],screenshots:['hostname','url','image','status','captured_at','error'],cve:['hostname','ip','port','banner','details','query','cve','edb_id','title','url','status'],events:['created_at','stage','level','event_type','message','details']}
const filters:Record<string,string[]>={hosts:['new','unchanged','no-longer-observed'],ports:['open','no-longer-observed'],services:['open','new','changed','unchanged','no-longer-observed'],endpoints:['discovered','captured','error'],credentials:['not_attempted','not_supported','failed','successful','blocked','unknown'],screenshots:['pending','captured','error'],cve:['candidate','no_matches','skipped','error'],events:['info','warning','error']}
const columns=computed(()=>fields[tab.value].map(key=>({key,label:key==='hostname'?'Host':key==='cve'?'CVE':key.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())})))
function filterHost(ip:string){void router.replace({query:{tab:'services',services_search:ip}})}
</script>
<template><div class="metrics"><div class="panel metric" v-for="key in metrics" :key="key"><span>{{key.replaceAll('_',' ')}}</span><strong>{{run.counts[key]||0}}</strong></div></div><nav class="tabs" aria-label="Network result sections"><button v-for="name in tabs" :key="name" :aria-current="tab===name?'page':undefined" :class="{active:tab===name}" @click="router.replace({query:{...route.query,tab:name}})">{{name==='cve'?'CVE':name[0].toUpperCase()+name.slice(1)}}</button></nav><p v-if="tab==='cve'" class="muted">SearchSploit banner matches are candidates to review. They do not confirm a vulnerability; records without a CVE retain their Exploit-DB reference.</p><DataTable :key="tab+'-'+String(route.query.services_search||'')" :query-key="tab" :endpoint="`/runs/${run.id}/${tab}`" :columns="columns" :status-options="filters[tab]" :refresh="['queued','running','pausing','stopping'].includes(run.status)?3000:0" filter-status><template #url="{value}"><a v-if="tab==='cve' && /^https:\/\/www\.exploit-db\.com\/exploits\/\d+$/.test(value)" :href="value" target="_blank" rel="noopener">{{value}}</a><span v-else>{{value}}</span></template><template #ip="{value}"><button class="text-button" @click="filterHost(value)">{{value}}</button></template><template #credential_id="{value,row}">{{row.credential_label||`Credential ${String(value).slice(0,8)}…`}} · masked</template><template #image="{row}"><a v-if="row.content_url" :href="row.content_url" target="_blank" rel="noopener"><img class="thumbnail" :src="row.thumbnail_url" :alt="`Screenshot of ${row.url}`" loading="lazy"></a><span v-else>Unavailable</span></template><template #screenshot="{row}"><button class="text-button" @click="router.replace({query:{tab:'screenshots',screenshots_search:row.url}})">View captures</button></template></DataTable></template>
